#!/usr/bin/env node
// Produces one self-contained schema from the generated modular schemas.
//
// The modular files cross-reference each other relatively, and a relative $ref
// resolves against the absolute $id — so a consumer holding only one file would
// have to fetch its sibling over the network. The bundle removes that: it is a
// single document with no external reference, so validation works offline and
// never depends on any host being reachable.
//
// Generated and committed. Edit the schema/*.graphql layers, never generated/.

import { readFileSync, writeFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

const at = (p) => fileURLToPath(new URL(`../${p}`, import.meta.url));
const read = (p) => JSON.parse(readFileSync(at(p), "utf8"));

/** Rewrite cross-file refs to local ones, and lift a schema's own $defs. */
function localize(node, defsPrefix) {
  if (Array.isArray(node)) return node.map((n) => localize(n, defsPrefix));
  if (node === null || typeof node !== "object") return node;
  const out = {};
  for (const [key, value] of Object.entries(node)) {
    if (key === "$ref" && typeof value === "string") {
      // A cross-file reference lands on the shared primitives, which are
      // bundled unprefixed. Only a schema's own local refs get its namespace,
      // or a primitive would be looked up under the wrong name.
      out[key] = value.startsWith("primitives.schema.json#/$defs/")
        ? value.replace(/^primitives\.schema\.json#\/\$defs\//, "#/$defs/")
        : value.replace(/^#\/\$defs\//, `#/$defs/${defsPrefix}`);
      continue;
    }
    if (key === "$id" || key === "$schema") continue;
    out[key] = localize(value, defsPrefix);
  }
  return out;
}

/** A schema's local $defs are namespaced so two documents cannot collide. */
function extractDefs(schema, prefix) {
  const defs = {};
  for (const [name, def] of Object.entries(schema.$defs ?? {})) {
    defs[`${prefix}${name}`] = localize(def, prefix);
  }
  return defs;
}

const body = (schema, prefix) => {
  const { $defs: _defs, $id: _id, $schema: _schema, ...rest } = schema;
  return localize(rest, prefix);
};

/**
 * Namespacing keeps two documents' local definitions apart, but a shared
 * primitive named `CapabilitiesX` would land on the same key as capabilities'
 * own `X` and be silently overwritten. Fail instead of shipping a bundle whose
 * refs resolve to the wrong schema.
 */
function assertNoCollisions(groups) {
  const seen = new Map();
  for (const [label, defs] of groups) {
    for (const name of Object.keys(defs)) {
      if (seen.has(name)) {
        throw new Error(
          `bundle $defs collision: "${name}" produced by both ${seen.get(name)} and ${label}`,
        );
      }
      seen.set(name, label);
    }
  }
}

export function buildBundle({
  primitives,
  event,
  capabilities,
  mapping,
  operations,
}) {
  const protocolVersion = event.$id?.match(
    /\/((?:0|[1-9]\d*)\.(?:0|[1-9]\d*))\/commerce-event\.schema\.json$/u,
  )?.[1];
  if (!protocolVersion) {
    throw new Error("commerce-event schema has no canonical protocol version");
  }

  const schemaBase = new URL(".", event.$id).href;
  for (const [name, schema] of [
    ["primitives", primitives],
    ["provider-capabilities", capabilities],
    ["store-event-mapping", mapping],
    ["operations", operations],
  ]) {
    if (new URL(".", schema.$id).href !== schemaBase) {
      throw new Error(`${name} schema does not share the protocol version`);
    }
  }

  const primitiveDefs = extractDefs(primitives, "");
  const capabilityDefs = extractDefs(capabilities, "Capabilities");
  const mappingDefs = extractDefs(mapping, "Mapping");
  // Operation documents keep their own names: they are what the binding
  // manifest and the OpenAPI components reference, and none may shadow a
  // primitive — assertNoCollisions turns a future clash into a build failure.
  const operationDefs = extractDefs(operations, "");

  assertNoCollisions([
    ["primitives", primitiveDefs],
    ["provider-capabilities", capabilityDefs],
    ["store-event-mapping", mappingDefs],
    ["operations", operationDefs],
    [
      "document roots",
      { CommerceEvent: 1, ProviderCapabilities: 1, StoreEventMapping: 1 },
    ],
  ]);

  return {
    $schema: "https://json-schema.org/draft/2020-12/schema",
    $id: new URL("commerce-protocol.bundle.schema.json", event.$id).href,
    title: `OpenIAP Commerce Protocol ${protocolVersion} (self-contained)`,
    description:
      "Every schema in this specification, in one document with no external reference. Validate against #/$defs/CommerceEvent, #/$defs/ProviderCapabilities, #/$defs/StoreEventMapping, or any operation input/result definition. Generated from commerce-protocol.graphql — do not edit this file.",
    $defs: {
      ...primitiveDefs,
      ...capabilityDefs,
      ...mappingDefs,
      ...operationDefs,
      CommerceEvent: body(event, ""),
      ProviderCapabilities: body(capabilities, "Capabilities"),
      StoreEventMapping: body(mapping, "Mapping"),
    },
  };
}

if (
  process.argv[1] &&
  fileURLToPath(import.meta.url) === resolve(process.argv[1])
) {
  const bundle = buildBundle({
    primitives: read("generated/schemas/primitives.schema.json"),
    event: read("generated/schemas/commerce-event.schema.json"),
    capabilities: read("generated/schemas/provider-capabilities.schema.json"),
    mapping: read("generated/schemas/store-event-mapping.schema.json"),
    operations: read("generated/schemas/operations.schema.json"),
  });
  const target = at("generated/schemas/commerce-protocol.bundle.schema.json");
  const serialized = `${JSON.stringify(bundle, null, 2)}\n`;

  if (process.argv.includes("--check")) {
    const current = readFileSync(target, "utf8");
    if (current !== serialized) {
      console.error(
        "generated/schemas/commerce-protocol.bundle.schema.json is stale. Run: node scripts/build-bundle.mjs",
      );
      process.exit(1);
    }
    console.log("bundle is current");
  } else {
    writeFileSync(target, serialized);
    console.log(`wrote ${target}`);
  }
}
